pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "Dead Space" (gaps smaller than the smallest possible item, 
    // approximated here as 10). If post_residual is in (0, 10), it's likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10.0 - post_residual as f64);
    }

    // 2. Lookahead optimization: If next_item_size is large, prefer bins 
    // that have enough space to accommodate it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Global pressure: Penalize opening new bins if we have many already, 
    // unless the fit is extremely tight (Best Fit).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 2.0;
    }

    // 4. Tightness reward: Heavily favor bins where post_residual is 0 
    // or very close to 0 to maximize capacity utilization.
    if post_residual == 0 {
        score -= 15.0;
    }

    // 5. Progression awareness: As we near the end of the stream, 
    // prioritize closing existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 40.0;
    }

    // 6. Avoid fragmented space: If we have many fitting bins, 
    // discourage picking a bin that results in a high post_residual.
    if fitting_bins_count > 1 {
        score += (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit)
    // The base score is already post_residual.

    // 2. Lookahead Integration: If next item fits in post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (1.0 - progress);
    }

    // 3. Fragmentation Avoidance: Penalize residuals that are too small to fit common items 
    // but large enough to waste space. Specifically penalize range [1, 9].
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. Global State Awareness: If we are near the end of the stream, 
    // be more aggressive about packing tightly (Best Fit).
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // 5. New Bin Logic: If the bin is new, impose a high entry cost. 
    // Only pay this cost if no other bin is a "good" fit.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, but scale it down as we open more bins 
        // to prevent extreme fragmentation early on.
        score += 40.0 - (open_bins_count as f64 * 0.5);
    }

    // 6. Fitting Pressure: If this is the only bin that fits the current item, 
    // reward placing it here to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 7. Residual Balance: Penalize bins that deviate significantly from the mean residual
    // to encourage uniform fill levels across open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize values that 
    // are too small to fit common items (e.g., < 10) unless it's a perfect match.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - (post_residual as f64 * 2.5);
    }

    // 2. Lookahead Logic: If the next item fits into the current post_residual, 
    // prioritize this bin highly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Mean Residual Balancing: Penalize bins that deviate significantly from 
    // the average usage, preventing fragmented bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.15;

    // 4. New Bin Thresholding: If this is a new bin (residual == capacity), 
    // only choose it if the current fitting options are extremely poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many bins open and the mean residual is already high,
        // or if fitting_bins_count is very low, making the current options inefficient.
        score += 40.0;
        score -= (open_bins_count as f64) * 0.5;
    } else {
        // If it's an existing bin, favor it to reduce open_bins_count
        score -= (fitting_bins_count as f64) * 2.0;
    }

    // 5. Progression scaling: As we reach the end of the stream, prioritize 
    // tighter packing to close bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If post_residual is small but > 0, it's likely "fragmentation".
    // We penalize residuals in the range (0, 10) as they are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead optimization: If next item exists, favor bins that leave enough space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can accommodate the next item.
        } else {
            score += 10.0; // Penalize bins that cannot accommodate the next item.
        }
    }

    // 3. Open bins pressure: Control the trade-off between packing density and fragmentation.
    // If we have many open bins, prioritize packing into existing ones (lower score).
    // If we have very few, be more selective to avoid creating "bad" bins.
    let density_factor = (open_bins_count as f64) / (1.0 + (step_index as f64 / total_items as f64) * 10.0);
    score += density_factor * 2.0;

    // 4. New bin handling:
    // If this is a new bin (bin_residual == bin_capacity), apply a baseline cost.
    // We only open a new bin if the score is lower than existing bins.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless existing bins are all "bad" (high residual).
        score = 45.0 + (mean_residual * 0.5);
    }

    // 5. Critical fit: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}
